export function TimelineItem(e,n){const i=n?n.color:"#FF6B35";return`<div class="timeline-item" data-law-id="${e.lawId}" style="--item-color: ${i}">\n    <div class="timeline-dot" style="background: ${i}"></div>\n    <div class="timeline-content">\n      <span class="timeline-year">${e.year}</span>\n      <h4 class="timeline-title">${n?n.name:e.lawId}</h4>\n      <p class="timeline-event">${e.event}</p>\n    </div>\n  </div>`}